import{mountTeacherWork}from './homework-work.js';
import{homeworkMarkup,mountHomeworkEditor}from './lesson-homework.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const codePattern=/^[\w-]{32}$/;
export const classroomInviteUrl=code=>codePattern.test(code||'')?'https://skodytunez-maker.github.io/salah/#lesson?invite='+code:null;
export function mountLessonPlans({root,api,post,onStart,notify=()=>{},now=Date.now}){
 const doc=root.ownerDocument,section=doc.createElement('section');section.className='lesson-plans';section.innerHTML='<div class="lesson-plan-heading"><div><span class="lesson-overline">РАСПИСАНИЕ</span><h2>Занятия с учениками SALAH</h2></div><button type="button" class="button" data-new>Запланировать</button></div><p class="lesson-note">Общая ссылка на один урок. Ученики входят под своим аккаунтом. Преподаватель запускает видеокомнату перед началом.</p><div data-form></div><div data-list role="status">Загружаем расписание…</div><div data-homework></div><div data-invite></div>';
 root.querySelector('.lesson-list')?.before(section);
 let stopHomework=null;const homeworkHost=section.querySelector('[data-homework]');function closeHomework(){stopHomework?.();stopHomework=null;homeworkHost.replaceChildren();}function showWorks(row){closeHomework();stopHomework=mountTeacherWork(homeworkHost,{lesson:row,call:(action,data)=>post('plans/'+row.id+'/'+action,data),isActive:active});homeworkHost.scrollIntoView?.({block:'nearest'});}function editHomework(row){closeHomework();stopHomework=mountHomeworkEditor(homeworkHost,{lesson:row,onCancel:closeHomework,onSave:async(homework,expectedHomeworkRevision)=>{await post('plans/'+row.id+'/homework',{homework,expectedHomeworkRevision});if(active()){closeHomework();await refresh();}}});homeworkHost.scrollIntoView?.({block:'nearest'});}
 let disposed=false,revision=0;const active=()=>!disposed&&section.isConnected,formHost=section.querySelector('[data-form]'),list=section.querySelector('[data-list]'),invitation=section.querySelector('[data-invite]');
 const format=l=>new Intl.DateTimeFormat('ru-RU',{timeZone:l.timeZone,day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}).format(l.startsAt);
 function form(row=null){
  const zone=row?.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone;
  let date=row?.date||new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now());
  if(!row&&new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',hourCycle:'h23'}).format(now())>='20')date=new Date(Date.parse(date+'T12:00:00Z')+86400000).toISOString().slice(0,10);
  formHost.innerHTML='<form class="lesson-form lesson-plan-form"><h2>'+(row?'Изменить занятие':'Запланировать занятие')+'</h2><label>Тема<input name="title" maxlength="100" required value="'+esc(row?.title||'')+'" placeholder="Таджвид, арабский язык и другие темы"></label><label>Преподаватель<input name="teacherName" maxlength="48" required value="'+esc(row?.teacherName||'')+'"></label><div class="lesson-plan-fields"><label>Дата<input name="date" type="date" required value="'+esc(date)+'"></label><label>Начало<input name="time" type="time" required value="'+esc(row?.time||'20:00')+'"></label></div><label>Часовой пояс<input name="timeZone" required maxlength="80" value="'+esc(zone)+'"><small>Указанные часы относятся к этому часовому поясу.</small></label><div class="lesson-plan-fields"><label>Длительность<select name="minutes">'+[30,45,60,90].map(n=>'<option value="'+n+'"'+((row?.minutes||60)===n?' selected':'')+'>'+n+' минут</option>').join('')+'</select></label><label>Всего участников<select name="maxParticipants">'+Array.from({length:9},(_,i)=>i+2).map(n=>'<option value="'+n+'"'+((row?.maxParticipants||10)===n?' selected':'')+'>'+n+', включая преподавателя</option>').join('')+'</select></label></div><label>Напомнить в день урока<input name="reminderTime" type="time" required value="'+esc(row?.reminderTime||'17:00')+'"></label><p class="lesson-note">Уведомление получат записавшиеся ученики, которые выбрали напоминание и подключили уведомления. Если указанное время уже прошло, старое напоминание отправляться не будет.</p><p class="lesson-error" role="alert"></p><div class="button-row"><button type="submit" class="button">Сохранить занятие</button><button type="button" class="lesson-text-button" data-cancel-form>Отмена</button></div></form>';
  const f=formHost.querySelector('form');f.querySelector('[data-cancel-form]').onclick=()=>formHost.replaceChildren();
  f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');if(b.disabled)return;b.disabled=true;const data=Object.fromEntries(new FormData(f));data.minutes=Number(data.minutes);data.maxParticipants=Number(data.maxParticipants);try{await post(row?'plans/'+row.id+'/update':'plans',data);if(active()){formHost.replaceChildren();await refresh();}}catch(error){if(active()){f.querySelector('[role=alert]').textContent=error.message;b.disabled=false;}}};
  f.querySelector('input').focus();
 }
 async function invite(row,b){b.disabled=true;try{const value=await post('plans/'+row.id+'/invite');const url=classroomInviteUrl(value.code);if(!url)throw Error('Приглашение пока недоступно.');if(!active())return;invitation.innerHTML='<section class="lesson-invite-box"><div class="lesson-invite-head"><strong>Общая ссылка для учеников</strong><button type="button" class="lesson-invite-close" aria-label="Закрыть приглашение">×</button></div><p>Одна ссылка на занятие. Для записи нужен аккаунт SALAH; после завершения урока вход закроется.</p><input readonly aria-label="Ссылка на занятие" value="'+esc(url)+'"><button class="button" type="button" data-copy>Скопировать приглашение</button><p role="status"></p></section>';invitation.querySelector('.lesson-invite-close').onclick=()=>invitation.replaceChildren();invitation.querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(url);if(active())invitation.querySelector('[role=status]').textContent='Приглашение скопировано.';}catch{if(active()){invitation.querySelector('input').select();invitation.querySelector('[role=status]').textContent='Выделите и скопируйте ссылку.';}}};}catch(e){notify(e.message);}finally{b.disabled=false;}}
 async function refresh(){
  const rev=++revision;try{const rows=await api('plans');if(!active()||rev!==revision)return;list.replaceChildren();if(!rows.length){list.textContent='Пока нет запланированных занятий.';return;}
   for(const row of rows){const card=doc.createElement('article');card.className='lesson-card lesson-plan-card';const ended=['cancelled','ended'].includes(row.state);card.innerHTML='<div><span class="lesson-live-label">'+esc({planned:'Запланировано',live:'Урок идёт',ended:'Завершён',cancelled:'Отменён'}[row.state]||'Занятие')+'</span><h3>'+esc(row.title)+'</h3><p>'+esc(format(row))+' · '+esc(row.timeZone)+'</p><p>'+esc(row.teacherName)+' · до '+row.maxParticipants+' участников</p><small>Напоминание в '+esc(row.reminderTime)+' в день занятия</small></div><div class="lesson-plan-actions"></div>';const actions=card.querySelector('.lesson-plan-actions');
    const add=(text,run,disabled=false)=>{const b=doc.createElement('button');b.className='button secondary';b.type='button';b.textContent=text;b.disabled=disabled;b.onclick=()=>run(b);actions.append(b);return b;};
    if(!ended){add('Пригласить',b=>invite(row,b),!row.hasInvite);if(row.state==='planned'){add('Изменить',()=>form(row));let confirming=false;add('Отменить занятие',async b=>{if(!confirming){confirming=true;b.textContent='Подтвердить отмену';return;}b.disabled=true;try{await post('plans/'+row.id+'/cancel');await refresh();}catch(e){notify(e.message);b.disabled=false;}});}add(row.state==='live'?'Открыть комнату':'Начать занятие',async b=>{b.disabled=true;try{const l=await post('plans/'+row.id+'/start');if(active())await onStart(l.id);}catch(e){notify(e.message);b.disabled=false;}},now()<row.startsAt-15*60000||now()>=row.endsAt);}
    if(row.state!=='cancelled'){add(row.homework?'Изменить ДЗ':'Добавить ДЗ',()=>editHomework(row));if(row.homework)add('Работы учеников',()=>showWorks(row));const box=doc.createElement('div');box.innerHTML=homeworkMarkup(row.homework);card.append(...box.childNodes);}
    list.append(card);
   }
  }catch(e){if(active()&&rev===revision){list.textContent=e.message;const retry=doc.createElement('button');retry.type='button';retry.className='lesson-text-button';retry.textContent='Повторить';retry.onclick=()=>void refresh();list.append(retry);}}
 }
 section.querySelector('[data-new]').onclick=()=>form();void refresh();
 return()=>{disposed=true;revision++;closeHomework();section.remove();};
}
